'use strict';
const assert=require('assert/strict'),fs=require('fs'),path=require('path'),sharp=require('sharp'),{performance}=require('perf_hooks');const {factory}=require('./harness.cjs');
let checks=0;const ok=(v,m)=>{assert.ok(v,m);checks++},rig=factory(),base=factory(true),views=[0,45,90,135,180,225,270,315].flatMap(yaw=>[6,35,78].map(pitch=>[yaw,pitch]));
const svg=(h,yaw,pitch,label='')=>`<svg xmlns="http://www.w3.org/2000/svg" width="600" height="600" viewBox="-105 -105 210 210"><rect x="-105" y="-105" width="210" height="210" fill="#faf8f2"/>${h.render(yaw,pitch)}${label?`<text x="-100" y="100" font-size="6" fill="#231e16">${label}</text>`:''}</svg>`;
const atoms=s=>(s.replace(/<mask\b[\s\S]*?<\/mask>/g,'').match(/<(?:path|text)\b[^>]*(?:>[^<]*<\/text>|\/?>)/g)||[]).sort().join('\n');
const samples={musicbox:[],turntable:[],camera:[]};const capture=(h,name)=>samples[h.id].push({name,s:JSON.parse(JSON.stringify(h.s))});
{
 const h=rig('musicbox');capture(h,'open');h.act('lid');for(let i=0;i<13;i++){h.tick(.04);capture(h,'closing-'+i)}h.act('lid');for(let i=0;i<13;i++){h.tick(.04);capture(h,'reverse-'+i)}h.tick(1);ok(h.s.lid===1&&h.callbacks.size===0,'reversed lid returns fully open');h.act('lid');h.tick(1);capture(h,'closed');h.act('crank');h.tick(.15);capture(h,'closed-crank');h.button('重新开始');h.tick(1);ok(h.s.angle===0&&h.s.lid===1&&h.callbacks.size===0,'reset stops crank and lid');
 const before=base('musicbox');for(const lid of[0,.2,.39999,.40001,.6,1])for(const [yaw,pitch]of views){h.s.lid=before.s.lid=lid;h.s.angle=before.s.angle=.3;ok(atoms(h.render(yaw,pitch))===atoms(before.render(yaw,pitch)),`paper geometry/material atoms unchanged ${lid}/${yaw}/${pitch}`)}
}
function distanceSegments(p1,q1,p2,q2){const sub=(a,b)=>a.map((v,k)=>v-b[k]),dot=(a,b)=>a.reduce((s,v,k)=>s+v*b[k],0),add=(p,d,t)=>p.map((v,k)=>v+d[k]*t),clamp=x=>Math.max(0,Math.min(1,x)),d1=sub(q1,p1),d2=sub(q2,p2),r=sub(p1,p2),a=dot(d1,d1),e=dot(d2,d2),b=dot(d1,d2),c=dot(d1,r),f=dot(d2,r),den=a*e-b*b;let s=den?clamp((b*f-c*e)/den):0,t=(b*s+f)/e;if(t<0){t=0;s=clamp(-c/a)}else if(t>1){t=1;s=clamp((b-c)/a)}return Math.hypot(...sub(add(p1,d1,s),add(p2,d2,t)))}
function clearance(s){const a=.03+s.arm*(.35+s.elapsed/36*.28),z=27+s.lift*4,mid=[13+30*Math.cos(a-.08),11+30*Math.sin(a-.08),z+1],end=[13+39*Math.cos(a),11+39*Math.sin(a),z];return Math.min(...[8.1,11.3].flatMap(y=>[[[13,11,30],mid],[mid,end]].map(([p,q])=>distanceSegments(p,q,[40,y,30.7],[40,y,32])-1.05-.45)))}
let minSwingClearance=Infinity,actionFrames=0;
{
 const h=rig('turntable');capture(h,'rest');
 function tick(seconds,label){for(let t=0;t<seconds-1e-9;t+=.01){const old=h.s.arm;h.tick(.01);actionFrames++;if(Math.abs(h.s.arm-old)>1e-8){ok(h.s.lift>=1.649,'lateral movement only above fork tips');const gap=clearance(h.s);minSwingClearance=Math.min(minSwingClearance,gap);ok(gap>.05,'moving tube clears both fork rods');}if(actionFrames%10===0)capture(h,label+'-'+actionFrames)}}
 h.act('cue');tick(.8,'inward');ok(h.s.arm===1&&h.s.lift===1&&h.s.cue==='hover','inward sequence raises, swings and settles');h.act('cue');tick(.5,'lower');ok(h.s.lift===0,'stylus settles at groove');h.act('play');tick(9,'play');h.act('play');const elapsed=h.s.elapsed;tick(1,'pause');ok(h.s.elapsed===elapsed&&h.s.platterRpm===0,'pause stops motor but preserves groove');h.act('cue');tick(.2,'lift');h.button('唱臂归位');tick(2,'park');ok(h.s.arm===0&&h.s.lift===1&&h.s.elapsed===0&&h.s.cue==='rest','park settles vertically on original support');
 for(const seconds of [.03,.18,.4,.66]){h.act('cue');tick(seconds,'partial');h.button('唱臂归位');tick(2,'reversal');ok(h.s.arm===0&&h.s.lift===1&&h.s.cue==='rest','mid-transfer park has no fork collision');}
 h.act('cue');tick(.8,'inward');h.act('cue');tick(.5,'lower');h.act('play');tick(37,'full-side');tick(2,'auto-return');ok(h.s.ended&&h.s.elapsed===36&&h.s.arm===0&&h.s.lift===1&&h.s.cue==='rest','complete side safely returns');h.act('cue');tick(.2,'reset-inward');h.button('重新开始');tick(2,'reset');ok(h.s.arm===0&&h.s.lift===1&&h.callbacks.size===0,'reset invalidates every driver');
 for(const t of[0,9,18,27,36]){const a=.38+t/36*.28,x=13+41*Math.cos(a),y=11+41*Math.sin(a);ok(Math.hypot(x-36,y-36)>=8&&Math.hypot(x-36,y-36)<=22,'needle tracks grooved band');ok(27-2.7===24.3,'needle contact z stays at groove height');}
}
{
 const h=rig('camera');const roller=()=>{h.render(45,35);return h.cfg.scene.layers.find(p=>p.key==='roller')?.svg};ok(roller(),'fixed roller present at idle');capture(h,'idle');
 for(let i=0;i<5;i++){h.act('shutter');for(const t of[.15,.2,.7,.7,1.6,2]){h.tick(t);capture(h,'shot-'+i+'-'+h.s.phase)}ok(h.s.phase==='ready','each photo reaches ready');const old=roller();h.act('collect');h.tick(.48);ok(h.s.collected===i+1&&h.s.phase==='idle','collect finishes once');ok(roller()===old,'roller spin stays continuous across sheet collection');capture(h,'collected-'+i)}
 h.button('装入相纸');h.tick(.45);capture(h,'loading');h.tick(.6);ok(h.s.frames===5&&h.s.phase==='idle','reload completes');
 for(const phase of['idle','flash','ejecting','developing','ready','collecting','loading']){h.s.phase=phase;h.s.eject=1;const out=roller();ok(out,'roller always exists during '+phase);h.s.phase='ejecting';ok(out===roller(),'phase switch cannot pop or rotate fixed roller '+phase)}
 for(const seconds of[.1,.8,2.3,5.5]){h.button('重新开始');h.act('shutter');h.tick(seconds);h.button('重新开始');h.tick(7);ok(h.s.phase==='idle'&&h.s.frames===5&&h.s.collected===0&&h.callbacks.size===0,'reset cancels camera phase '+seconds)}
 for(const event of['pointercancel','lostpointercapture']){h.event('pointerdown',{key:'shutter'});h.event(event);ok(h.s.frames===5&&h.s.shutterPress===0,'cancelled shutter does not expose');}
}
let rendered=0;for(const [id,states]of Object.entries(samples)){const h=rig(id);for(const {name,s}of states.filter((v,i)=>id!=='turntable'||i%8===0||/inward|park|reversal|reset|return/.test(v.name))){Object.assign(h.s,s);for(const [yaw,pitch]of views){const out=h.render(yaw,pitch);ok(out.length>1000&&!/NaN|Infinity|undefined/.test(out),id+' finite '+name);rendered++;}}}
async function png(h,yaw,pitch){return sharp(Buffer.from(svg(h,yaw,pitch))).png().toBuffer()}
async function changed(a,b){const A=await sharp(a).removeAlpha().raw().toBuffer(),B=await sharp(b).removeAlpha().raw().toBuffer();let n=0;for(let i=0;i<A.length;i+=3)if(Math.max(...[0,1,2].map(k=>Math.abs(A[i+k]-B[i+k])))>20)n++;return n}
(async()=>{
 const pops=[];for(const yaw of[0,45,90,135,180,225,270,315])for(const pitch of[6,35,78]){const row={yaw,pitch};for(const [tag,f]of[['before',base],['after',rig]]){const h=f('musicbox');h.s.lid=.39999;const a=await png(h,yaw,pitch);h.s.lid=.40001;const b=await png(h,yaw,pitch);row[tag]=await changed(a,b);if(yaw===180&&pitch===35){fs.writeFileSync(path.join(__dirname,`${tag}-lid-threshold-low.png`),a);fs.writeFileSync(path.join(__dirname,`${tag}-lid-threshold-high.png`),b);}}ok(row.after<80,`no .4 threshold pop at ${yaw}/${pitch}`);pops.push(row)}
 // Same-world-state before/after photos: the roller survives the phase change.
 for(const [tag,f]of[['before',base],['after',rig]]){const h=f('camera');h.s.eject=1;h.s.phase='ejecting';const a=await png(h,45,35);h.s.phase='developing';const b=await png(h,45,35);fs.writeFileSync(path.join(__dirname,`${tag}-camera-ejection-end.png`),a);fs.writeFileSync(path.join(__dirname,`${tag}-camera-development-start.png`),b);if(tag==='after')ok(await changed(a,b)===0,'camera ejection/development transition has zero geometric pixel pop')}
 const timing={};for(const id of['musicbox','turntable','camera']){timing[id]={};for(const [tag,f]of[['before',base],['after',rig]]){const h=f(id);if(id==='musicbox')Object.assign(h.s,{lid:.4});if(id==='turntable')Object.assign(h.s,{arm:.2,lift:1.65});if(id==='camera')Object.assign(h.s,{phase:'ejecting',eject:.5});for(let i=0;i<10;i++)h.render(45,35);const times=[];for(let round=0;round<5;round++){const start=performance.now();for(let i=0;i<30;i++){h.s.angle=i/10;h.render(45,35)}times.push((performance.now()-start)/30)}times.sort((a,b)=>a-b);timing[id][tag]={medianMs:times[2],roundsMs:times};}timing[id].ratio=timing[id].after.medianMs/timing[id].before.medianMs;}
 const result={checks,actionFrames,renderedStateViews:rendered,minSwingClearance,thresholdPops:pops,timings:timing,limits:'Deterministic Node VM plus Sharp SVG raster. Browser interaction, paint performance, and native audio are separate parent/reviewer checks.'};fs.writeFileSync(path.join(__dirname,'results.json'),JSON.stringify(result,null,2));console.log(JSON.stringify(result,null,2));
})().catch(e=>{console.error(e);process.exitCode=1});
